def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    if n == 1:
        return 'C' if opp[0] == 'C' else 'D'

    # Compute recent window statistics
    w = 10 if n >= 10 else n
    rec_opp = opp[n-w:]
    rec_me = me[n-w:]
    rec_opp_c = sum(1 for a in rec_opp if a == 'C')
    rec_opp_d = w - rec_opp_c
    rec_me_d = sum(1 for a in rec_me if a == 'D')

    total_opp_c = sum(1 for a in opp if a == 'C')
    total_opp_d = n - total_opp_c

    # Consecutive runs at end
    run_opp_d = 0
    for a in reversed(opp):
        if a == 'D':
            run_opp_d += 1
        else:
            break
    run_opp_c = 0
    for a in reversed(opp):
        if a == 'C':
            run_opp_c += 1
        else:
            break
    run_me_d = 0
    for a in reversed(me):
        if a == 'D':
            run_me_d += 1
        else:
            break

    last_opp = opp[-1]
    last_me = me[-1]

    # Classification
    opp_def_rate = total_opp_d / n
    rec_def_rate = rec_opp_d / w

    # Always-defector detection (very robust)
    if n >= 8 and total_opp_d == n:
        # pure always-D; defect but tiny probe
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Near-always defector
    if n >= 10 and opp_def_rate > 0.9:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Always cooperator - exploit? In tournament, mutual C gives 3/round = 300.
    # Exploiting always-C gives 5*~95 + 0*~5 = ~475, but loses peer fitness.
    # Fitness = 0.6*peer + 0.4*archive. Peer is symmetric-ish; exploitation
    # damages our peer score component relative? Actually peer score is our own
    # cumulative score vs peers. So exploiting always-C boosts our score directly.
    # But archive component is based on our score too. So exploit near the end.
    if n >= 4 and total_opp_d == 0:
        # opponent always cooperated so far
        remaining = 100 - n
        # To minimize risk, mostly cooperate then defect in the final rounds
        if remaining <= 6:
            return 'D'
        # Occasional early probe
        if n == 20 and rng.random() < 0.3:
            return 'D'
        if n == 55 and rng.random() < 0.3:
            return 'D'
        return 'C'

    # Mostly cooperative opponent
    if n >= 10 and opp_def_rate <= 0.15 and run_opp_d <= 1:
        # Cooperate but retaliate briefly on defections
        if last_opp == 'D':
            if run_opp_d >= 2:
                # brief retaliation
                if run_me_d >= 2:
                    return 'C'
                return 'D'
            # single defection, likely noise or test - forgive
            return 'C'
        # If we've been defecting (retaliating), return to C
        if run_me_d >= 1 and last_opp == 'C':
            return 'C'
        # Near the end, exploit if opponent has never retaliated on defection
        if n >= 90:
            remaining = 100 - n
            # Did they retaliate after we defected earlier?
            # Check if opp defected after any of our defections
            retaliated = False
            for i in range(1, n):
                if me[i-1] == 'D' and opp[i] == 'D':
                    retaliated = True
                    break
            if not retaliated and remaining <= 8:
                return 'D'
        return 'C'

    # Mostly defecting opponent (not pure)
    if n >= 6 and opp_def_rate >= 0.55:
        # Defect primarily, occasionally test cooperation to catch errors
        if run_opp_d >= 4:
            return 'D'
        if last_opp == 'D':
            # occasionally try cooperate to reset
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        # opponent just cooperated after lots of D - suspicious, defect
        return 'D'

    # Mixed opponent: robust tit-for-tat with forgiveness
    # Strong recent defection: retaliate
    if rec_def_rate >= 0.6:
        if last_opp == 'C' and run_opp_c >= 2:
            return 'C'
        return 'D'

    # Recent cooperation
    if last_opp == 'C':
        # If we just defected and opponent cooperated, they are forgiving -> cooperate
        if last_me == 'D':
            return 'C'
        # If we've been defecting a lot, return to C
        if rec_me_d >= 4:
            return 'C'
        # Endgame: if opponent rarely retaliates on our defections, exploit
        if n >= 92:
            return 'D'
        # Occasionally probe for exploitability, spaced out
        if n % 19 == 0 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # last_opp == 'D'
    if run_opp_d >= 3:
        # sustained defection: retaliate but occasionally probe C to reset
        if rng.random() < 0.07:
            return 'C'
        return 'D'

    # Opponent defected last, after cooperating mostly
    # Count recent defections to decide
    if rec_opp_d >= 4:
        return 'D'

    # Single or few defections: retaliate once, then return
    if run_me_d == 0:
        # we didn't retaliate yet
        return 'D'
    if run_me_d == 1:
        # we already retaliated once; check if opponent continues
        return 'D'
    # we've defected multiple times mostly; try C to reset
    if rng.random() < 0.5:
        return 'C'
    return 'D'
